<!doctype html>
<html lang="id">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Persetujuan Waka - PresensiKita</title>
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#eef2f7;color:#1e293b;margin:0;padding:20px}.box{width:100%;max-width:620px;margin:20px auto;background:#fff;border-radius:14px;padding:26px;box-shadow:0 8px 24px #0f172a1f}h1{font-size:22px;margin:0 0 8px}.intro{color:#64748b;font-size:13px;line-height:1.5}.info{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px}.row{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid #e2e8f0;font-size:13px}.row:last-child{border:0}.label{color:#64748b}.decision{border-top:1px solid #e2e8f0;margin-top:20px;padding-top:18px}h2{font-size:16px;color:#7c3aed}textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;font:inherit;resize:vertical;margin-bottom:10px}button{border:0;border-radius:8px;padding:11px 16px;color:#fff;font-weight:700;cursor:pointer}.approve{background:#16a34a}.reject{background:#dc2626;margin-left:6px}.status{display:inline-block;border-radius:6px;padding:6px 9px;background:#fef3c7;color:#92400e;font-size:12px;font-weight:700}.done{background:#dcfce7;color:#166534}.declined{background:#fee2e2;color:#991b1b}@media(max-width:520px){body{padding:10px}.box{margin:0 auto;padding:20px}.row{display:block}.row strong,.row .status{display:block;margin-top:4px}.reject{margin-left:4px}}</style>
</head>
<body><main class="box"><h1>Persetujuan Izin Guru</h1><p class="intro">Halaman khusus Wakil Kepala Sekolah. Tidak perlu login untuk memberikan keputusan.</p><section class="info"><div class="row"><span class="label">Guru</span><strong>{{ $izin->guru->nama_guru ?? '-' }}</strong></div><div class="row"><span class="label">Tanggal izin</span><strong>{{ $izin->tanggal_izin->format('d-m-Y') }}</strong></div><div class="row"><span class="label">Dimintakan oleh</span><strong>{{ $izin->guruPiket->nama_guru ?? '-' }}</strong></div><div class="row"><span class="label">Alasan</span><strong>{{ $izin->alasan }}</strong></div></section><div class="decision"><h2>Keputusan Waka</h2><div class="row"><span class="label">Status</span><span class="status {{ $izin->status_waka === 'disetujui' ? 'done' : ($izin->status_waka === 'ditolak' ? 'declined' : '') }}">{{ ucfirst($izin->status_waka) }}</span></div>@if(session('approval_message'))<p style="color:#166534;font-weight:700">{{ session('approval_message') }}</p>@endif @if($izin->status_waka === 'menunggu')<form method="POST" action="{{ $approvalUrl }}" onsubmit="return konfirmasiKeputusan(event, 'Waka')">@csrf<textarea name="catatan" rows="3" placeholder="Catatan (opsional)"></textarea><button class="approve" name="keputusan" value="disetujui">Setujui Izin</button><button class="reject" name="keputusan" value="ditolak">Tolak Izin</button></form>@else<p class="intro">Keputusan Waka sudah diberikan.</p>@endif</div></main><script>function konfirmasiKeputusan(event,role){event.preventDefault();const form=event.target;const isReject=event.submitter&&event.submitter.value==='ditolak';Swal.fire({title:isReject?'Tolak izin guru?':'Setujui izin guru?',text:'Keputusan sebagai '+role+' akan disimpan.',icon:isReject?'warning':'question',showCancelButton:true,confirmButtonText:isReject?'Ya, tolak izin':'Ya, setujui izin',cancelButtonText:'Batal',confirmButtonColor:isReject?'#dc2626':'#16a34a',cancelButtonColor:'#64748b',reverseButtons:true}).then(result=>{if(result.isConfirmed){const hidden=document.createElement('input');hidden.type='hidden';hidden.name='keputusan';hidden.value=isReject?'ditolak':'disetujui';form.appendChild(hidden);form.submit()}})}</script></body></html>
